"use client";import {FormEvent,useState} from "react";import type {BuyerRequest} from "@/lib/types";
export function RequestManager({initial}:{initial:BuyerRequest[]}){const [items,setItems]=useState(initial);const [notice,setNotice]=useState("");async function save(e:FormEvent<HTMLFormElement>,id:number){e.preventDefault();setNotice("Saving…");const body=Object.fromEntries(new FormData(e.currentTarget));const response=await fetch(`/api/staff/requests/${id}`,{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});const data=await response.json();if(response.ok){setItems(v=>v.map(x=>x.id===id?data:x));setNotice("Buyer workflow updated. No sale was completed.")}else setNotice(data.detail||"Could not update request.")}return <><p role="status" className="notice">{notice}</p>{items.map(i=><form className="panel request manageRequest" key={i.id} onSubmit={e=>save(e,i.id)}><div><span className="status">{i.status}</span><h2>{i.name}</h2><p>{i.kind} for <strong>{i.vehicle_title}</strong></p><p>{i.message}</p><small>{i.email} · {i.phone}</small></div><div className="workflow"><label>Status<select name="status" defaultValue={i.status}><option value="new">New</option><option value="contacted">Contacted</option><option value="scheduled">Scheduled</option><option value="closed">Closed</option></select></label><label>Scheduled for<input type="datetime-local" name="scheduled_for" defaultValue={i.scheduled_for?.slice(0,16)||""}/></label>{i.kind==="offer"&&<><label>Offer decision<select name="offer_status" defaultValue={i.offer_status}><option value="pending">Pending review</option><option value="countered">Counteroffer sent</option><option value="accepted">Accepted — sale not completed</option><option value="declined">Declined</option></select></label><label>Counteroffer<input type="number" name="counter_offer_amount" min="0" defaultValue={i.counter_offer_amount||""}/></label></>}<label>Staff note<textarea name="staff_note" defaultValue={i.staff_note}/></label><button className="button">Update workflow</button><small>Accepting an offer does not mark the car Sold.</small></div></form>)}</>}
